import copy,json,struct,tempfile,unittest
from pathlib import Path
from fixture import create,cfg

class ManifestTests(unittest.TestCase):
 def setUp(self):
  self.tmp=tempfile.TemporaryDirectory();self.addCleanup(self.tmp.cleanup);self.p=Path(self.tmp.name);self.meta,self.m=create(self.p/'a')
 def mutate(self,edit):
  changed=copy.deepcopy(self.m);edit(changed)
  with self.assertRaises(ValueError):cfg.validate(changed,self.m)
 def test_reference_words(self):
  # Independent constants, not generated by the fixture encoder.
  self.assertEqual(cfg.decode(0x1000,0x38600009)['text'],'li r3,9')
  self.assertEqual(cfg.decode(0x1000,0x48000009)['target'],0x1008)
  self.assertEqual(cfg.decode(0x1000,0x9421ffb0)['memory']['offset'],-80)
  self.assertEqual(cfg.decode(0x1000,0x4e800421)['kind'],'indirect_call')
 def test_canonical_order(self):
  reordered=json.loads(json.dumps(self.m,sort_keys=False));self.assertEqual(cfg.canonical(reordered),cfg.canonical(self.m))
  events=[{k:v for k,v in s.items() if k!='index'} for s in reversed(self.m['policy']['sites'])]
  self.assertEqual(cfg.coalesce(events),self.m['policy']['sites'])
 def test_repeat_generation(self):
  meta,m=create(self.p/'b');self.assertEqual(m,self.m)
  for name in ['fixture.xex','fixture_manifest.toml','region.json']:self.assertEqual((self.p/'a'/name).read_bytes(),(self.p/'b'/name).read_bytes())
 def test_hash_binding(self):self.mutate(lambda m:m['bindings'].__setitem__('xex_sha256','0'*64))
 def test_rehashed_forgery(self):
  changed=copy.deepcopy(self.m);changed['policy']['sites'].pop();changed['policy_sha256']=cfg.sha(cfg.canonical(changed['policy']));changed['namespace']=cfg.sha(cfg.canonical({'bindings':changed['bindings'],'policy_sha256':changed['policy_sha256']}))
  with self.assertRaises(ValueError):cfg.validate(changed,self.m)
 def test_duplicate_coalescing(self):
  event={k:v for k,v in self.m['policy']['sites'][0].items() if k!='index'}
  self.assertEqual(len(cfg.coalesce([event,event])),1)
  bad=copy.deepcopy(event);bad['owner']+=4
  with self.assertRaises(ValueError):cfg.coalesce([event,bad])
 def test_missing_site(self):self.mutate(lambda m:m['policy']['sites'].pop())
 def test_invalid_edge(self):self.mutate(lambda m:m['policy']['edges'].append([1,2]))
 def test_unknown_indirect(self):self.mutate(lambda m:next(s for s in m['policy']['sites'] if s['kind']=='indirect_call')['targets'].append(0xdead0000))
 def test_unexpected_exit(self):self.mutate(lambda m:next(s for s in m['policy']['sites'] if s['action']=='exit').__setitem__('action','execute'))
 def test_index_mismatch(self):self.mutate(lambda m:m['policy']['sites'][0].__setitem__('index',1))
 def test_unsupported_event(self):
  e={k:v for k,v in self.m['policy']['sites'][0].items() if k!='index'};e['events'].append('guest-unwind')
  with self.assertRaises(ValueError):cfg.coalesce([e])
 def test_namespace_changes(self):
  for key in self.m['bindings']:
   changed=copy.deepcopy(self.m);changed['bindings'][key]='1'*len(changed['bindings'][key]);self.assertNotEqual(cfg.sha(cfg.canonical({'bindings':changed['bindings'],'policy_sha256':changed['policy_sha256']})),self.m['namespace'])
 def test_complete_stop_proof(self):self.assertEqual(self.meta['proof'],{'sites':74,'stops':74,'backedges':2,'uncovered_cycles':0})
 def test_cycle_requires_stop(self):
  changed=copy.deepcopy(self.m);pc=self.meta['named']['spin'];next(s for s in changed['policy']['sites'] if s['pc']==pc)['events'].remove('stop')
  with self.assertRaises(ValueError):cfg.stop_proof(changed)
 def test_required_boundary_requires_stop(self):
  changed=copy.deepcopy(self.m);next(s for s in changed['policy']['sites'] if s['action']=='exit')['events'].remove('stop')
  with self.assertRaises(ValueError):cfg.stop_proof(changed)
 def test_shared_or_invalid_ranges(self):
  raw=struct.pack('>II',0x38600009,0x4e800020);f={'start':0x1000,'end':0x1008,'owner_start':0x1000,'owner_end':0x1008};bindings={k:('0'*64) for k in ['xex_sha256','patch_lock_sha256','codegen_config_sha256']};bindings['cli_revision']=cfg.REVISION
  for ranges in [[f,f],[{**f,'end':0x100c}]]:
   with self.assertRaises(ValueError):cfg.build(raw,0x1000,ranges,[0x1000],[],{},{},bindings)
 def test_branch_escape_requires_boundary(self):
  raw=struct.pack('>I',0x48000010);f={'start':0x1000,'end':0x1004,'owner_start':0x1000,'owner_end':0x1004}
  with self.assertRaises(ValueError):cfg.build(raw,0x1000,[f],[0x1000],[],{},{},{'xex_sha256':'0'*64,'patch_lock_sha256':'0'*64,'codegen_config_sha256':'0'*64,'cli_revision':cfg.REVISION})
 def test_unknown_instruction(self):
  for w in [0x7c602028,0x00000000]:
   with self.assertRaises(ValueError):cfg.decode(0x1000,w)
 def test_emitted_anchor_rejection(self):
  row=cfg.decode(0x1000,0x48000009);text='\t// bl 0x1008\nctx.lr = 0x1004;\n'
  self.assertEqual(cfg.reconcile([row],text)['matched_instructions'],1)
  for bad in [text.replace('0x1004','0x100C'),text.replace('0x1008','0x100C'),text+'\t// blr\nreturn;\n']:
   with self.assertRaises(ValueError):cfg.reconcile([row],bad)

 def test_hook_refusal_and_extern_declarations(self):
  rows=[cfg.decode(0x1000,0x38600009),cfg.decode(0x1004,0x4e800020)]
  body='\t// li r3,9\n\tbrutal_cfg_1000();\n\t// blr\n\tbrutal_cfg_1004();\nreturn;\nextern void brutal_cfg_1008();\n'
  self.assertEqual(cfg.reconcile_hooks(rows,body,[0x1000,0x1004]),[0x1000,0x1004])
  for bad in [body.replace('\tbrutal_cfg_1000();\n',''),body.replace('\tbrutal_cfg_1000();','\tbrutal_cfg_1004();')]:
   with self.assertRaises(ValueError):cfg.reconcile_hooks(rows,bad,[0x1000,0x1004])
 def test_labels_and_callee_anchors(self):
  row=cfg.decode(0x1000,0x48000009);body='\t// bl 0x1008\nctx.lr = 0x1004;\nREX_CALL_FUNC(original);\n'
  cfg.reconcile([row],body,function_map={'original':0x1008})
  with self.assertRaises(ValueError):cfg.reconcile([row],body,function_map={'original':0x1010})
  with self.assertRaises(ValueError):cfg.reconcile([cfg.decode(0x1000,0x38600009)],'loc_1004:\n\t// li r3,9\n')

if __name__=='__main__':unittest.main()
